<?php /** 출퇴근 시스템 DB 설정 버튼 실행 페이지 */ require_once __DIR__.'/../app/bootstrap.php'; if(!\App\Core\Auth::canManageEmployees()){die('권한없음');} $pdo=\App\Core\Db::pdo(); if(!$pdo){die('DB 연결 실패');} $sqls=array(
"CREATE TABLE IF NOT EXISTS cpms_attendance_records (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, work_date DATE NOT NULL, check_in DATETIME NULL, check_out DATETIME NULL, status VARCHAR(30) NOT NULL DEFAULT '출근전', work_minutes INT NOT NULL DEFAULT 0, memo VARCHAR(255) DEFAULT '', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_emp_date(employee_id,work_date), INDEX idx_work_date(work_date), INDEX idx_employee_id(employee_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS cpms_attendance_requests (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, request_date DATE NOT NULL, request_type VARCHAR(30) NOT NULL, requested_check_in DATETIME NULL, requested_check_out DATETIME NULL, reason TEXT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', reviewed_by INT NULL, reviewed_at DATETIME NULL, reject_reason TEXT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_employee_id(employee_id), INDEX idx_request_date(request_date), INDEX idx_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS cpms_leave_records (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, leave_date DATE NOT NULL, leave_type VARCHAR(30) NOT NULL, leave_amount DECIMAL(4,2) NOT NULL DEFAULT 1.0, reason VARCHAR(255) DEFAULT '', created_by INT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_employee_id(employee_id), INDEX idx_leave_date(leave_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS cpms_leave_adjustments (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, leave_type VARCHAR(30) NOT NULL, amount DECIMAL(6,2) NOT NULL, reason VARCHAR(255) DEFAULT '', created_by INT NULL, created_at DATETIME NOT NULL, INDEX idx_employee_id(employee_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS cpms_attendance_settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL, updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
); foreach($sqls as $q){$pdo->exec($q);} $now=date('Y-m-d H:i:s'); $seed=array('standard_weekly_hours'=>'40','max_weekly_hours'=>'52','under_one_year_monthly_leave'=>'1','half_day_amount'=>'0.5','leave_rule_after_one_year'=>'half_year','week_start'=>'monday'); foreach($seed as $k=>$v){$st=$pdo->prepare("REPLACE INTO cpms_attendance_settings(setting_key,setting_value,updated_at) VALUES(:k,:v,:u)");$st->execute(array(':k'=>$k,':v'=>$v,':u'=>$now));} echo 'OK';